		public void TestNonUSEntryLineIsExcluded()
		{
			var zzCompanyPK = Guid.NewGuid();
			var zzBranchPK = CreateGlbBranch("ZZ", zzCompanyPK);
			var zzDeclaration = CreateData(zzBranchPK, zzCompanyPK, "ZZ", "ACE", "IMP", "01", "ACE", ValuationDateType.ExportDate, 1);
			var sql = @"SELECT COUNT(1) FROM dbo.USImportEntryInvoiceLine";
			using (var command = Db.Connection.Command(sql))
			{
				AssertEquals("Non-US declaration should be excluded", 0, command.ExecuteScalar());
			}
		}

