		void AssertData(string indicator, IDataReader reader, ExpectedResult expectedResult)
		{
			Assert(indicator + " has row", reader.Read());
			var actualDeclarationReference = (string)reader[JobDeclarationSchema.Constants.JE_DeclarationReference];
			var actualInvoiceNumber = (string)reader[USImportEntryInvoiceLineSchema.Constants.USL_InvoiceNumber];
			var actualLineNo = (short)reader[USImportEntryInvoiceLineSchema.Constants.USL_LineNo];
			indicator += $" {actualDeclarationReference}-{actualInvoiceNumber}-{actualLineNo} ";
			AssertEquals(indicator + JobDeclarationSchema.Constants.JE_DeclarationReference, expectedResult.DeclarationReference, (string)reader[JobDeclarationSchema.Constants.JE_DeclarationReference]);
			AssertEquals(indicator + USImportEntryInvoiceLineSchema.Constants.PK, expectedResult.PK, (Guid)reader[USImportEntryInvoiceLineSchema.Constants.PK]);
			AssertEquals(indicator + USImportEntryInvoiceLineSchema.Constants.USL_JE, expectedResult.USL_JE, (Guid)reader[USImportEntryInvoiceLineSchema.Constants.USL_JE]);
			AssertGuid(indicator, reader, USImportEntryInvoiceLineSchema.Constants.USL_JI_ParentProduct, expectedResult.USL_JI_ParentProduct);
			AssertEquals(indicator + USImportEntryInvoiceLineSchema.Constants.USL_JZ, expectedResult.USL_JZ, (Guid)reader[USImportEntryInvoiceLineSchema.Constants.USL_JZ]);
			AssertEquals(indicator + USImportEntryInvoiceLineSchema.Constants.USL_LineNo, expectedResult.USL_LineNo, (short)reader[USImportEntryInvoiceLineSchema.Constants.USL_LineNo]);
			AssertEquals(indicator + USImportEntryInvoiceLineSchema.Constants.USL_LinePrice, expectedResult.USL_LinePrice, (decimal)reader[USImportEntryInvoiceLineSchema.Constants.USL_LinePrice]);
			AssertEquals(indicator + USImportEntryInvoiceLineSchema.Constants.USL_MessageType, expectedResult.USL_MessageType, (string)reader[USImportEntryInvoiceLineSchema.Constants.USL_MessageType]);
