		void AssertGuid(string indicator, IDataReader reader, string fieldName, Guid expectedValue)
		{
			var dbValue = reader[fieldName];
			var value = dbValue == DBNull.Value ? Guid.Empty : (Guid)dbValue;
			AssertEquals(indicator + fieldName, expectedValue, value);
		}

		void AssertDate(string indicator, IDataReader reader, string fieldName, DateTime expectedValue)
		{
			var dbValue = reader[fieldName];
			var value = dbValue == DBNull.Value ? DateTime.MinValue : (DateTime)dbValue;
			AssertEquals(indicator + fieldName, expectedValue, value);
		}

