		Guid CreateGlbBranch(string countryCode, Guid companyPK)
		{
			var branchPK = Guid.NewGuid();
			var branchSql = @"
INSERT INTO dbo.GlbCompany (GC_PK, GC_Code, GC_Name, GC_RN_NKCountryCode, GC_RX_NKLocalCurrency) 
VALUES (@CompanyPK, @CountryCode + 'C', 'US company', @CountryCode, @CountryCode + 'D')

INSERT INTO dbo.GlbBranch (GB_PK, GB_Code, GB_GC)
VALUES (@BranchPK, @CountryCode + 'B', @CompanyPK)
";

			using (var command = Db.Connection.Command(branchSql))
			{
				command.AddParameter("@CountryCode", SqlDbType.Char, countryCode);
				command.AddParameter("@BranchPK", SqlDbType.UniqueIdentifier, branchPK);
				command.AddParameter("@CompanyPK", SqlDbType.UniqueIdentifier, companyPK);
				command.ExecuteNonQuery();
			}
			return branchPK;
		}

		enum ValuationDateType { LatestRateDate, ExportDate, Today }
		(Guid DeclarationPK, Guid EntryPK, Guid EntryLine1PK, Guid EntryLine2PK, Guid EntryLine3PK, Guid EntryLine4PK, Guid Invoice1PK, Guid Invoice2PK, Guid InvoiceLine1PK, Guid InvoiceLine2PK, Guid InvoiceLine3PK, Guid InvoiceLine4PK) CreateData(Guid branchPK, Guid companyPK, string prefix, string applicationCode, string messageType, string entryType, string cargoReleaseType, ValuationDateType valuationDateType, int clusterKey)
		{
			var valuationDateString = "";
			switch (valuationDateType)
			{
				case ValuationDateType.ExportDate:
					valuationDateString = "*DateOfExport=2020-04-06";
					break;
				case ValuationDateType.LatestRateDate:
					valuationDateString = "*LatestRateDate=2020-03-31*DateOfExport=2020-04-06";
					break;
			}
			var addInfo = $"EntryType={entryType}*CargoReleaseType={cargoReleaseType}{valuationDateString}*ITDate=2020-04-03*EstimatedEntryDate=2020-04-09*PreliminaryStatementPrintDate=2020-04-06*EntryDate=2020-04-10*PresentationDate=2020-04-11*TotalEnteredValue=1000";
			var declarationPK = Guid.NewGuid();
			var entryPK = Guid.NewGuid();
			var entryLine1PK = Guid.NewGuid();
			var entryLine2PK = Guid.NewGuid();
			var entryLine3PK = Guid.NewGuid();
			var entryLine4PK = Guid.NewGuid();
			var invoice1PK = Guid.NewGuid();
			var invoice2PK = Guid.NewGuid();
			var invoiceLine1PK = Guid.NewGuid();
			var invoiceLine2PK = Guid.NewGuid();
			var invoiceLine3PK = Guid.NewGuid();
			var invoiceLine4PK = Guid.NewGuid();
			var declarationReference = $"{prefix}{applicationCode}{messageType}{entryType}{cargoReleaseType}".PadRight(15, '0');
			var creationSql = @"
INSERT dbo.JobDeclaration (JE_PK, JE_DataModel, JE_DeclarationReference, JE_GB, JE_GC, JE_ApplicationCode, JE_MessageType, JE_DateOfArrival, JE_EntryAuthorisationDate, JE_AddInfo, JE_ClusterKey)
VALUES (@DeclarationPK, 'US', @DeclarationReference, @BranchPK, @CompanyPK, @ApplicationCode, @MessageType, '2020-04-01', '2020-04-15', @AddInfo, @ClusterKey)

