VALUES
(NEWID(), 'US', @DeclarationPK, 'ENS', @DeclarationReference + '-ENS1', 'IsDeactivated=N*DutyCalcDate=2020-04-02', @ClusterKey, getutcdate(), '~BP', getutcdate(), '~BP'),
(NEWID(), 'US', @DeclarationPK, 'ENS', @DeclarationReference + '-ENS2', 'IsDeactivated=Y*DutyCalcDate=2020-04-12', @ClusterKey, getutcdate(), '~BP', getutcdate(), '~BP'),
(NEWID(), 'US', @DeclarationPK, 'ENS', @DeclarationReference + '-ENS3', 'IsDeactivated=N*DutyCalcDate=2020-04-08', @ClusterKey, getutcdate(), '~BP', getutcdate(), '~BP'),
(@EntryPK, 'US', @DeclarationPK, 'EN1', @DeclarationReference + '-EN11', 'IsDeactivated=N*DutyCalcDate=2020-04-13', @ClusterKey, getutcdate(), '~BP', getutcdate(), '~BP');

