	JZ_AddInfo, JZ_ClusterKey)
VALUES (@Invoice1PK, 'US', @DeclarationPK, 'INV1', 1, 'FOB', 0.5, 'FIX', 'AUD', 0, 'DateOfExport=2020-04-05*ZoneStatus=D*PrivilegedStatusDate=2020-04-04', @ClusterKey)

