	JI_CustomsQuantity, JI_CustomsUnitQty, JI_CustomsSecondQuantity, JI_CustomsSecondUnitQty, JI_CustomsThirdQuantity, JI_CustomsThirdUnitQty, JI_AddInfo, JI_ClusterKey)
